/**
 * Build `actions_array` dynamically from the API payload instead of static arrays.
 *
 * Inputs already in scope:
 *   - actions_array_name : the DDL selection (e.g. "before_ticket_issuance_actions_array")
 *   - channel            : "Email" | "Phone" | "Chat"
 *   - customer_action    : the selected action name (DDL action selection)
 *   - edvin_errands : the full API response (channels -> categories -> types -> actions)
 *
 * Every DDL name maps to a type inside the "Cancellation" category.
 * Output shape stays the same as before: { name, tags, bucket, edvin_actions }.
 */

// THIS VALUE WILL COME AUTOMATICALLY FROM ZENDESK
// Map the Zendesk contact-reason field (custom_field_29559177650834) to the Edvin category name.
// Interim mapping (built our side) until Edvin returns a value that matches the Zendesk field directly.
const CONTACT_REASON_BY_ZENDESK = {
  "contact_reason__rebooking": "Rebooking",
  "contact_reason__cancellation": "Cancellation",
  "contact_reason__refund": "Refund",
  "contact_reason__name_correction_change": "Name correction/change",
  "contact_reason__add_passenger": "Add passenger/New ticket sell",
  "contact_reason__change_customers_personal_information": "Change customer's personal information",
  "contact_reason__document_travel_info": "Document & Travel info",
  "contact_reason__payment_question": "Payment Questions",
  "contact_reason__ancillaries_products": "Ancillaries/Services & Products",
  "contact_reason__unconfirmed_booking": "Unconfirmed booking",
  "contact_reason__site_support": "Site support",
  "contact_reason__ongoing_issues": "Ongoing issues",
  "contact_reason__other": "Other",
  "contact_reason__schedule_change": "Schedule Change" // no matching Edvin category (type only) - pending ETG
};
const CONTACT_REASON = CONTACT_REASON_BY_ZENDESK[ZT.getVariableValue("custom_field_29559177650834", "Cancellation")] || "";

// UPDATE THIS VALUE WITH SAME VALUES FROM NODE 1
// DDL selection -> the matching type name inside the Cancellation category.

// stitch type + edvin config details
let type_id = ZT.getVariableValue("type", "");
let selected_type = transforms.category.types.find(x => {
  if (x.id == type_id) {
    return x;
  }
})

let edvin_errands = actions.edvin__errand_configuration;
let edvin_prop_long_val = actions.get_edvin_prop_long_value;

let { channel, category } = transforms;
const type = selected_type.name;
const ids = {
  channelId: channel.id,
  categoryId: category.id,
  typeId: type_id
};

// Normalize each API action into a clean, string-typed shape. The Edvin API
// returns `bucket` as an object; downstream routing needs the scalar bucket key
// ("proceed" | "no_action" | "escalate" | "different_request"). Unknown shapes
// fall back to "" -> the "default" bucket (a safe silent ticket, never "proceed").
function bucketKey(b) {
  if (typeof b === "string") return b;
  return (b && (b.name || b.value || b.key || b.label)) || "";
}

const actions_array = selected_type.actions.map(action => ({
  ...action,
  bucket: bucketKey(action.bucket),
  actionId: action.id
}));

ZT.log("action bucket shapes: " + JSON.stringify(selected_type.actions.map(a => a.bucket)));
ZT.setTransformData("actions_array", actions_array);

// Record this errand on the running list of customer-action PNRs.
let current_pnr = {
  ...transforms.current_pnr,
  channel: channel.name,
  channelId: ids.channelId,
  category: category.name,
  categoryId: ids.categoryId,
  type,
  typeId: ids.typeId,
  notes,
  actions_array
  // actionId / customer_action added downstream after the action is selected
};

// Upsert by PNR so re-running this node for an already-recorded PNR
// (Back navigation, or a ?session_id= deep-resume that re-enters past node 24)
// overwrites that PNR's record instead of adding a duplicate action card.
let customer_action_pnrs = transforms.customer_action_pnrs || [];
let existingIndex = customer_action_pnrs.findIndex(p => p.pnr === current_pnr.pnr);
if (existingIndex >= 0) {
  customer_action_pnrs[existingIndex] = current_pnr;
} else {
  customer_action_pnrs.push(current_pnr);
}
ZT.setTransformData("customer_action_pnrs", customer_action_pnrs);

